package controller;

import java.io.IOException;
import java.io.PrintWriter;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import java.util.List;
import dao.AssessmentDAO;
import dao.CourseDAO;
import model.Assessment;
import model.Course;

/**
 *
 * @author Legion
 */
@WebServlet(name = "AssessmentController", urlPatterns = {"/assessment"})
public class AssessmentController extends HttpServlet {

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String action = request.getParameter("action");
        AssessmentDAO assessmentDAO = new AssessmentDAO();
        CourseDAO courseDAO = new CourseDAO();

        if (action == null) {
            action = "list";
        }

        switch (action) {
            case "list":
                String courseIdStr = request.getParameter("courseId");
                if (courseIdStr != null && !courseIdStr.isEmpty()) {
                    try {
                        int courseId = Integer.parseInt(courseIdStr);
                        Course course = courseDAO.getCourseById(courseId);
                        if (course != null) {
                            List<Assessment> assessments = assessmentDAO.getAssessmentsByCourse(courseId);
                            double totalWeight = assessmentDAO.getTotalWeightByCourse(courseId);

                            request.setAttribute("course", course);
                            request.setAttribute("assessments", assessments);
                            request.setAttribute("totalWeight", totalWeight);
                            request.setAttribute("home_view", "/academic/assessment_management.jsp");
                            request.getRequestDispatcher("dashboard.jsp").forward(request, response);
                        } else {
                            response.sendError(HttpServletResponse.SC_NOT_FOUND);
                        }
                    } catch (NumberFormatException e) {
                        response.sendError(HttpServletResponse.SC_BAD_REQUEST);
                    }
                } else {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST);
                }
                break;

            case "delete":
                String assessmentIdStr = request.getParameter("assessmentId");
                String coursIdStr = request.getParameter("courseId");
                if (assessmentIdStr != null && !assessmentIdStr.isEmpty() && coursIdStr != null) {
                    try {
                        int assessmentId = Integer.parseInt(assessmentIdStr);
                        int courseId = Integer.parseInt(coursIdStr);

                        boolean success = assessmentDAO.deleteAssessment(assessmentId);
                        HttpSession session = request.getSession();
                        if (success) {
                            session.setAttribute("message", "Assessment deleted successfully");
                            session.setAttribute("messageType", "success");
                        } else {
                            session.setAttribute("message", "Failed to delete assessment");
                            session.setAttribute("messageType", "error");
                        }
                        response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseId);
                    } catch (NumberFormatException e) {
                        response.sendError(HttpServletResponse.SC_BAD_REQUEST);
                    }
                } else {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST);
                }
                break;

            default:
                response.sendError(HttpServletResponse.SC_NOT_FOUND);
                break;
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String action = request.getParameter("action");
        AssessmentDAO assessmentDAO = new AssessmentDAO();

        if (action == null) {
            action = "add";
        }

        switch (action) {
            case "add":
                String courseIdStr = request.getParameter("courseId");
                String assessmentName = request.getParameter("assessmentName");
                String weightStr = request.getParameter("weight");

                if (courseIdStr == null || courseIdStr.isEmpty() || assessmentName == null || assessmentName.trim().isEmpty() || weightStr == null || weightStr.isEmpty()) {
                    HttpSession session = request.getSession();
                    session.setAttribute("message", "All fields are required");
                    session.setAttribute("messageType", "error");
                    response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseIdStr);
                    return;
                }

                try {
                    int courseId = Integer.parseInt(courseIdStr);
                    double weight = Double.parseDouble(weightStr);

                    // Validate weight is between 0 and 100
                    if (weight < 0 || weight > 100) {
                        HttpSession session = request.getSession();
                        session.setAttribute("message", "Weight must be between 0 and 100");
                        session.setAttribute("messageType", "error");
                        response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseId);
                        return;
                    }

                    // Check total weight
                    double currentTotalWeight = assessmentDAO.getTotalWeightByCourse(courseId);
                    if (currentTotalWeight + weight > 100) {
                        HttpSession session = request.getSession();
                        session.setAttribute("message", "Total weight cannot exceed 100%. Current total: " + currentTotalWeight + "%");
                        session.setAttribute("messageType", "error");
                        response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseId);
                        return;
                    }

                    Assessment assessment = new Assessment();
                    assessment.setAssessmentName(assessmentName.trim());
                    assessment.setWeight(weight);

                    Course course = new Course();
                    course.setCourseId(courseId);
                    assessment.setCourse(course);

                    boolean success = assessmentDAO.addAssessment(assessment);
                    HttpSession session = request.getSession();
                    if (success) {
                        session.setAttribute("message", "Assessment added successfully");
                        session.setAttribute("messageType", "success");
                    } else {
                        session.setAttribute("message", "Failed to add assessment");
                        session.setAttribute("messageType", "error");
                    }
                    response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseId);
                } catch (NumberFormatException e) {
                    HttpSession session = request.getSession();
                    session.setAttribute("message", "Invalid number format");
                    session.setAttribute("messageType", "error");
                    response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseIdStr);
                }
                break;

            case "update":
                String assessmentIdStr = request.getParameter("assessmentId");
                String updCourseIdStr = request.getParameter("courseId");
                String updAssessmentName = request.getParameter("assessmentName");
                String updWeightStr = request.getParameter("weight");

                if (assessmentIdStr == null || assessmentIdStr.isEmpty() || updCourseIdStr == null || updCourseIdStr.isEmpty() ||
                    updAssessmentName == null || updAssessmentName.trim().isEmpty() || updWeightStr == null || updWeightStr.isEmpty()) {
                    HttpSession session = request.getSession();
                    session.setAttribute("message", "All fields are required");
                    session.setAttribute("messageType", "error");
                    response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + updCourseIdStr);
                    return;
                }

                try {
                    int assessmentId = Integer.parseInt(assessmentIdStr);
                    int courseId = Integer.parseInt(updCourseIdStr);
                    double weight = Double.parseDouble(updWeightStr);

                    // Validate weight is between 0 and 100
                    if (weight < 0 || weight > 100) {
                        HttpSession session = request.getSession();
                        session.setAttribute("message", "Weight must be between 0 and 100");
                        session.setAttribute("messageType", "error");
                        response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseId);
                        return;
                    }

                    // Get old weight to calculate difference
                    Assessment oldAssessment = assessmentDAO.getAssessmentById(assessmentId);
                    double oldWeight = (oldAssessment != null) ? oldAssessment.getWeight() : 0;
                    double weightDifference = weight - oldWeight;

                    // Check total weight
                    double currentTotalWeight = assessmentDAO.getTotalWeightByCourse(courseId);
                    if (currentTotalWeight + weightDifference > 100) {
                        HttpSession session = request.getSession();
                        session.setAttribute("message", "Total weight cannot exceed 100%. Current total would be: " + (currentTotalWeight + weightDifference) + "%");
                        session.setAttribute("messageType", "error");
                        response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseId);
                        return;
                    }

                    Assessment assessment = new Assessment();
                    assessment.setAssessmentId(assessmentId);
                    assessment.setAssessmentName(updAssessmentName.trim());
                    assessment.setWeight(weight);

                    Course course = new Course();
                    course.setCourseId(courseId);
                    assessment.setCourse(course);

                    boolean success = assessmentDAO.updateAssessment(assessment);
                    HttpSession session = request.getSession();
                    if (success) {
                        session.setAttribute("message", "Assessment updated successfully");
                        session.setAttribute("messageType", "success");
                    } else {
                        session.setAttribute("message", "Failed to update assessment");
                        session.setAttribute("messageType", "error");
                    }
                    response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + courseId);
                } catch (NumberFormatException e) {
                    HttpSession session = request.getSession();
                    session.setAttribute("message", "Invalid number format");
                    session.setAttribute("messageType", "error");
                    response.sendRedirect(request.getContextPath() + "/assessment?action=list&courseId=" + updCourseIdStr);
                }
                break;

            default:
                response.sendError(HttpServletResponse.SC_NOT_FOUND);
                break;
        }
    }

    @Override
    public String getServletInfo() {
        return "Assessment Management Controller";
    }
}

