            ps.setInt(3, newSlotId);
            ps.setInt(4, newTeacherId);
            ps.setInt(5, oldClassId);
            ps.setInt(6, oldRoomId);
            ps.setInt(7, oldSlotId);
            ps.setInt(8, oldTeacherId);
            return ps.executeUpdate();
