/**
 * Room Search Functionality
 * Handles real-time search filtering for room management table
 */

document.addEventListener('DOMContentLoaded', function() {
    const searchInput = document.getElementById('searchInput');
    const roomTable = document.getElementById('roomTable');
    const roomCount = document.getElementById('roomCount');

    if (!searchInput || !roomTable) return;

    const rows = roomTable.querySelectorAll('tbody tr');

    searchInput.addEventListener('keyup', function() {
        const searchTerm = this.value.toLowerCase().trim();
        let visibleCount = 0;

        rows.forEach(row => {
            const roomName = row.cells[1]?.textContent || '';
            const capacity = row.cells[2]?.textContent || '';
            const type = row.cells[3]?.textContent || '';

            const matches = roomName.toLowerCase().includes(searchTerm) ||
                           capacity.toLowerCase().includes(searchTerm) ||
                           type.toLowerCase().includes(searchTerm);

            row.style.display = matches ? '' : 'none';
            if (matches) visibleCount++;
        });

        if (roomCount) {
            roomCount.textContent = visibleCount;
        }

        // Show "no results" message if needed
        const tableContainer = roomTable.parentElement;
        let noResultsMsg = tableContainer.querySelector('.no-search-results');

        if (visibleCount === 0 && searchTerm !== '') {
            if (!noResultsMsg) {
                noResultsMsg = document.createElement('div');
                noResultsMsg.className = 'no-search-results text-center py-5 text-muted';
                noResultsMsg.innerHTML = '<i class="bx bx-search-alt" style="font-size: 2rem;"></i><p class="mt-2">No rooms found matching your search.</p>';
                tableContainer.appendChild(noResultsMsg);
            }
        } else if (noResultsMsg) {
            noResultsMsg.remove();
        }
    });

    // Clear search on Escape key
    searchInput.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            this.value = '';
            this.dispatchEvent(new Event('keyup'));
            this.focus();
        }
    });
});

/**
 * Room Search Functionality
 * Handles real-time search filtering for room management table
 */

document.addEventListener('DOMContentLoaded', function() {
    const searchInput = document.getElementById('searchInput');
    const roomTable = document.getElementById('roomTable');
    const roomCount = document.getElementById('roomCount');

    console.log('Room Search initialized:', { searchInput, roomTable, roomCount });

    if (!searchInput || !roomTable) {
        console.warn('Search input or room table not found');
        return;
    }

    const rows = roomTable.querySelectorAll('tbody tr');
    console.log('Found rows:', rows.length);

    searchInput.addEventListener('keyup', function() {
        const searchTerm = this.value.toLowerCase().trim();
        let visibleCount = 0;

        rows.forEach((row, index) => {
            // Extract text from cells: index(0), roomName(1), capacity(2), type(3), status(4), actions(5)
            const roomName = row.cells[1]?.textContent?.trim() || '';
            const capacity = row.cells[2]?.textContent?.trim() || '';
            const type = row.cells[3]?.textContent?.trim() || '';

            // Match against all three fields
            const matches = roomName.toLowerCase().includes(searchTerm) ||
                           capacity.toLowerCase().includes(searchTerm) ||
                           type.toLowerCase().includes(searchTerm);

            // Show or hide row
            row.style.display = matches ? '' : 'none';
            if (matches) {
                visibleCount++;
            }

            if (index === 0) {
                console.log('First row data:', { roomName, capacity, type, matches, searchTerm });
            }
        });

        // Update room count
        if (roomCount) {
            roomCount.textContent = visibleCount;
            console.log('Updated room count:', visibleCount);
        }

        // Show or hide "no results" message
        const tableContainer = roomTable.parentElement;
        let noResultsMsg = tableContainer.querySelector('.no-search-results');

        if (visibleCount === 0 && searchTerm !== '') {
            if (!noResultsMsg) {
                noResultsMsg = document.createElement('div');
                noResultsMsg.className = 'no-search-results text-center py-5 text-muted';
                noResultsMsg.innerHTML = '<i class="bx bx-search-alt" style="font-size: 2rem;"></i><p class="mt-2">No rooms found matching your search.</p>';
                tableContainer.appendChild(noResultsMsg);
            }
        } else if (noResultsMsg) {
            noResultsMsg.remove();
        }
    });

    // Clear search on Escape key
    searchInput.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            this.value = '';
            this.dispatchEvent(new Event('keyup'));
            this.focus();
        }
    });
});

